from typing import List

class Solution:
    def findPeakGrid(self, mat: List[List[int]]) -> List[int]:
        if not mat or not mat[0]:
            return []

        m = len(mat)
        n = len(mat[0])

        left, right = 0, n - 1

        while left < right:
            mid = (left + right) // 2

            # Find the row with maximum value in column mid
            max_row_idx = -1
            max_val = float('-inf')

            for i in range(m):
                if mat[i][mid] > max_val:
                    max_val = mat[i][mid]
                    max_row_idx = i

            # Check left neighbor (if exists)
            if mid == 0:
                left_neighbor_val = float('-inf')
            else:
                left_neighbor_val = mat[max_row_idx][mid - 1]

            # Check right neighbor (if exists)
            if mid == n - 1:
                right_neighbor_val = float('-inf')
            else:
                right_neighbor_val = mat[max_row_idx][mid + 1]

            # Check if current max is a peak (greater than all adjacent neighbors)
            if max_val > left_neighbor_val and max_val > right_neighbor_val:
                return [max_row_idx, mid]

            # Move toward the larger neighbor to potentially find a higher peak
            if right_neighbor_val > left_neighbor_val:
                left = mid + 1
            else:
                right = mid

        # Find peak in the final column
        col_idx = left
        max_row_idx = -1
        max_val = float('-inf')

        for i in range(m):
            if mat[i][col_idx] > max_val:
                max_val = mat[i][col_idx]
                max_row_idx = i

        return [max_row_idx, col_idx]
